// The filters, equalizers and pedals of the Faust libraries (filters.lib, vaeffects.lib) as modules: the
// functions of the libraries take their settings as arguments, so each module gives them an interface made
// for music, written here (body), and generated by build-faust-library-modules.mjs as the demos.
//
// - Cutoff (or Frequency) in Hz, on a log scale, 20 Hz to 20 kHz: an envelope or an LFO dropped on it moves
//   it in octaves (widget modulation, exponential).
// - Pitch on the filters: moves the cutoff, 0.1 per octave; a pitch dropped on it (a sequencer) makes the
//   cutoff follow the notes, as on the VCF of the modular library. The cutoff is kept from 20 Hz to 0.45 SR.
// - Q on a log scale; gains in dB; the responses of a filter and the orders in menus (labels without '-').
// - No smoothing of the settings (si.smoo), as the modules of the modular library: a modulation passes as is.
// - The filters of vaeffects.lib take a normalized frequency, mapped to 20*1000^normFreq Hz: the module
//   converts the cutoff, normFreq = log10(fc/20)/3.
//
// Their families (Lib filters, Lib equalizers, Lib pedals) are in FAUST_LIBRARY_FAMILIES, with the demos of
// demos.lib that belong to them. Each module: its family, name, file (in public/faust-modules/faustlib), the functions used (source), the
// lines of its description, its inlets and outlets, and its Faust code (body, after import("stdfaust.lib")).

const CUTOFF = (deflt = 1000) => `cutoff = hslider("[1]Cutoff[unit:Hz][scale:log]", ${deflt}, 20, 20000, 1);`;
const PITCH = `pitch = hslider("[2]Pitch[unit:pitch]", 0, -1, 1, 0.0001);`;
const FC = `// the cutoff moved by the pitch, 0.1 per octave
fc = cutoff * pow(2, 10 * pitch) : max(20) : min(0.45 * ma.SR);`;
const NORM = `// the normalized frequency of vaeffects.lib (20*1000^nf Hz)
nf = log10(fc / 20) / 3;`;
const Q = (deflt, min, max) => `q = hslider("[3]Q[scale:log]", ${deflt}, ${min}, ${max}, 0.001);`;
const menu = (index, label, items, deflt = 0) =>
    `hslider("[${index}]${label}[style:menu{${items.map((s, i) => `'${s}':${i}`).join(";")}}]", ${deflt}, 0, ${items.length - 1}, 1)`;
const MODE = (items) => `mode = ${menu(0, "Mode", items)};`;
const PITCH_LINE = "Pitch: moves the cutoff, 0.1 per octave; a pitch dropped on it (a sequencer) makes the cutoff follow the notes, its amount on the modulation port being the keyboard tracking";
const filter = (lines) => [...lines.slice(0, -1), "Cutoff in Hz; an envelope or an LFO dropped on it moves it in octaves", PITCH_LINE, lines[lines.length - 1]];
const AUDIO = { inlets: "audio", outlets: "audio" };

